#include <stdlib.h>

typedef struct {
  int *parent;   /* parent[i] == i means i is a root */
  int *size;     /* valid only at roots */
  int count;     /* number of sets */
} DSU;

void dsu_init(DSU *d, int n) {
  d->parent = malloc(n * sizeof(int));
  d->size = malloc(n * sizeof(int));
  d->count = n;
  for (int i = 0; i < n; i++) { d->parent[i] = i; d->size[i] = 1; }
}

int dsu_find(DSU *d, int x) {
  while (d->parent[x] != x) {
    d->parent[x] = d->parent[d->parent[x]];   /* path halving */
    x = d->parent[x];
  }
  return x;
}

int dsu_union(DSU *d, int a, int b) {        /* returns 1 if they were separate */
  int ra = dsu_find(d, a), rb = dsu_find(d, b);
  if (ra == rb) return 0;
  if (d->size[ra] < d->size[rb]) { int t = ra; ra = rb; rb = t; }
  d->parent[rb] = ra;                         /* attach smaller under larger */
  d->size[ra] += d->size[rb];
  d->count--;
  return 1;
}

typedef struct { int *parent; } NaiveDSU;

int find_naive(NaiveDSU *d, int i) {
  if (d->parent[i] == i) return i;          /* i is a root */
  return find_naive(d, d->parent[i]);       /* climb one level */
}

void unite_naive(NaiveDSU *d, int i, int j) {
  int irep = find_naive(d, i), jrep = find_naive(d, j);
  d->parent[irep] = jrep;                   /* i's root hangs under j's root */
}
